package com.mlserve.inference

import java.util.concurrent.{ConcurrentHashMap, ArrayBlockingQueue}
import java.security.MessageDigest
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec
import scala.collection.mutable
import scala.util.{Try, Success, Failure}

// Connection pool entry with cached auth context
case class PooledConnection(
  id: String,
  modelEndpoint: String,
  var lastAuthContext: AuthContext,
  var lastUsedTimestamp: Long,
  var requestCount: Long
)

case class AuthContext(
  userId: String,
  role: String,
  permissions: Set[String],
  tokenHash: String,
  validUntil: Long
)

case class InferenceRequest(
  modelId: String,
  inputData: Array[Double],
  token: String,
  requestedTier: String
)

case class InferenceResult(prediction: Array[Double], confidence: Double, modelVersion: String)

object ModelRegistry {
  val models: Map[String, String] = Map(
    "sentiment-v2" -> "standard",
    "fraud-detect-v3" -> "premium",
    "recommendation-v1" -> "standard",
    "risk-scoring-v4" -> "enterprise"
  )

  def getRequiredTier(modelId: String): String = models.getOrElse(modelId, "enterprise")
}

class ConnectionPool(maxSize: Int, ttlMs: Long) {
  private val pool = new ArrayBlockingQueue[PooledConnection](maxSize)
  private val activeConnections = new ConcurrentHashMap[String, PooledConnection]()

  def acquire(modelEndpoint: String, authCtx: AuthContext): PooledConnection = {
    val existing = Option(pool.poll())
    existing match {
      case Some(conn) if conn.modelEndpoint == modelEndpoint && !isExpired(conn) =>
        conn.lastUsedTimestamp = System.currentTimeMillis()
        conn.requestCount += 1
        // Update auth context to current request's context
        conn.lastAuthContext = authCtx
        activeConnections.put(conn.id, conn)
        conn
      case Some(conn) =>
        // Endpoint mismatch or expired, create new with fresh context
        val newConn = createConnection(modelEndpoint, authCtx)
        activeConnections.put(newConn.id, newConn)
        newConn
      case None =>
        val newConn = createConnection(modelEndpoint, authCtx)
        activeConnections.put(newConn.id, newConn)
        newConn
    }
  }

  def release(conn: PooledConnection): Unit = {
    activeConnections.remove(conn.id)
    if (!isExpired(conn)) {
      pool.offer(conn)
    }
  }

  private def isExpired(conn: PooledConnection): Boolean = {
    System.currentTimeMillis() - conn.lastUsedTimestamp > ttlMs
  }

  private def createConnection(endpoint: String, authCtx: AuthContext): PooledConnection = {
    PooledConnection(
      id = java.util.UUID.randomUUID().toString,
      modelEndpoint = endpoint,
      lastAuthContext = authCtx,
      lastUsedTimestamp = System.currentTimeMillis(),
      requestCount = 0
    )
  }
}

class InferenceServer(secretKey: String) {
  private val connectionPool = new ConnectionPool(maxSize = 50, ttlMs = 300000)
  private val tierHierarchy = Map("standard" -> 1, "premium" -> 2, "enterprise" -> 3)

  def validateToken(token: String): Option[AuthContext] = {
    Try {
      val parts = token.split("\\.")
      if (parts.length != 3) return None
      val payload = new String(java.util.Base64.getDecoder.decode(parts(1)))
      val claims = parseSimpleJson(payload)
      val userId = claims("sub")
      val role = claims("role")
      val tier = claims("tier")
      val exp = claims("exp").toLong

      // Verify HMAC signature
      val mac = Mac.getInstance("HmacSHA256")
      mac.init(new SecretKeySpec(secretKey.getBytes("UTF-8"), "HmacSHA256"))
      val signatureInput = s"${parts(0)}.${parts(1)}"
      val expectedSig = java.util.Base64.getUrlEncoder.withoutPadding().encodeToString(
        mac.doFinal(signatureInput.getBytes("UTF-8"))
      )

      // Constant-time comparison to prevent timing attacks
      if (!MessageDigest.isEqual(
            expectedSig.getBytes("UTF-8"),
            parts(2).getBytes("UTF-8")
          )) return None
      if (System.currentTimeMillis() / 1000 > exp) return None

      val permissions = role match {
        case "admin" => Set("standard", "premium", "enterprise")
        case "analyst" => Set("standard", "premium")
        case "viewer" => Set("standard")
        case _ => Set.empty[String]
      }

      Some(AuthContext(
        userId = userId,
        role = role,
        permissions = permissions,
        tokenHash = MessageDigest.getInstance("SHA-256")
          .digest(token.getBytes).map("%02x".format(_)).mkString,
        validUntil = exp
      ))
    }.getOrElse(None)
  }

  def handleInference(request: InferenceRequest): Either[String, InferenceResult] = {
    val authResult = validateToken(request.token)
    if (authResult.isEmpty) return Left("Authentication failed")
    val authCtx = authResult.get

    val requiredTier = ModelRegistry.getRequiredTier(request.modelId)
    val modelEndpoint = s"internal://${request.modelId}"

    // Acquire pooled connection
    val conn = connectionPool.acquire(modelEndpoint, authCtx)

    try {
      // Authorization check uses the current request's auth context
      // Connection pool updates context on acquire
      val effectiveAuth = conn.lastAuthContext
      val userTierLevel = tierHierarchy.getOrElse(
        effectiveAuth.permissions.maxByOption(p => tierHierarchy.getOrElse(p, 0)).getOrElse("standard"),
        0
      )
      val requiredTierLevel = tierHierarchy.getOrElse(requiredTier, 3)

      if (userTierLevel < requiredTierLevel) {
        Left(s"Insufficient permissions: requires $requiredTier tier access")
      } else {
        // Simulate model inference
        val result = InferenceResult(
          prediction = request.inputData.map(_ * 0.5),
          confidence = 0.95,
          modelVersion = s"${request.modelId}-latest"
        )
        Right(result)
      }
    } finally {
      connectionPool.release(conn)
    }
  }

  private def parseSimpleJson(json: String): Map[String, String] = {
    json.stripPrefix("{").stripSuffix("}")
      .split(",")
      .map(_.split(":", 2))
      .collect { case Array(k, v) => k.trim.stripPrefix("\"").stripSuffix("\"") -> v.trim.stripPrefix("\"").stripSuffix("\"") }
      .toMap
  }
}
